{
  "name": "bench-vitest",
  "private": true,
  "type": "module",
  "scripts": { "test": "vitest run" },
  "devDependencies": { "vitest": "5.0.3" }
}
import { fetchRates } from './rates.js';

export async function convert(amount, to) {
  let rates;
  try {
    rates = await fetchRates();
  } catch (cause) {
    throw new Error('Exchange rates are unavailable, try again later', { cause });
  }
  if (!(to in rates)) throw new Error(`Unknown currency: ${to}`);
  return Math.round(amount * rates[to] * 100) / 100;
}
import { describe, test, expect, vi } from 'vitest';
import { convert } from './convert.js';

describe('convert', () => {
  vi.mock('./rates.js', () => ({
    fetchRates: async () => ({ EUR: 0.9, JPY: 150 }),
  }));

  test('converts with the current rate', async () => {
    await expect(convert(10, 'EUR')).resolves.toBe(9);
  });

  test('rejects unknown currencies', async () => {
    await expect(convert(10, 'XYZ')).rejects.toThrow('Unknown currency: XYZ');
  });
});

